# -*- coding: utf-8 -*-
"""Lecture 29 vignette pool B -- Arrhythmias I: supraventricular tachycardia (stable vs unstable),
focal and multifocal atrial tachycardia, accessory pathway reentry and Wolff-Parkinson-White,
atrioventricular nodal reentry.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Procainamide is keyed only for PRE-EXCITED ATRIAL FIBRILLATION (irregular, wide, very fast, with
delta waves) -- where the course ("never adenosine") and the guideline agree. No stem asks for the
drug in a known-Wolff-Parkinson-White patient with a REGULAR narrow tachycardia (see the scope).
Emphasis from the recording: vagal maneuver first when stable ("listen, open your ears"), and the
Wolff-Parkinson-White history ("a high miss last year").
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l29_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


SVT = "Supraventricular tachycardia"
ATA = "Focal and multifocal atrial tachycardia"
AVR = "Accessory pathway reentry and Wolff-Parkinson-White"
NOD = "Atrioventricular nodal reentry"

